-- PART 7: VECTOR SEARCH (pgvector)
-- ---------------------------------------------------------------------
-- Embeddings are generated by the application (not SQL) and inserted, e.g.:
--   INSERT INTO incident_embeddings (incident_id, source_text, embedding, embedding_model)
--   VALUES ($1, $2, $3::vector, 'text-embedding-3-small');
--

-- ivfflat needs rows present when built; use lists ~ sqrt(row count)
CREATE INDEX idx_incident_embeddings_vector
ON incident_embeddings USING ivfflat (embedding vector_cosine_ops) WITH (lists = 10);

-- Similarity search ($1 = query embedding). <=> is cosine DISTANCE, so
-- similarity = 1 - distance.
-- SELECT i.incident_id, i.title, r.root_cause_description, r.resolution_summary,
--        ROUND((1 - (e.embedding <=> $1::vector))::NUMERIC * 100, 1) AS similarity_pct
